declaration:
FUNCTION_BLOCK FB_MaterialProportioning

VAR_INPUT
    estop : BOOL;             
    opeMode : BOOL;           
    valveAStart : BOOL;       
    valveBStart : BOOL;
    valveCStart : BOOL;
    valveDStart : BOOL;
    mixMotorStart : BOOL;
    autoStart : BOOL;         
    processMode : BOOL;       
    levelSensor : INT;        
    mixMotorComplete : BOOL;  
END_VAR
VAR_OUTPUT
    valveARun : BOOL;
    valveBRun : BOOL;
    valveCRun : BOOL;
    valveDRun : BOOL;
    mixMotorRun : BOOL;
END_VAR
VAR

    state : INT;

    prevAutoStart : BOOL;
    prevValveAStart : BOOL;
    prevValveBStart : BOOL;
    prevValveCStart : BOOL;
    prevValveDStart : BOOL;
    prevMixMotorStart : BOOL;
    prevOpeMode : BOOL;

    manA : BOOL;
    manB : BOOL;
    manC : BOOL;
    manD : BOOL;
    manMix : BOOL;
END_VAR

implementation:
IF NOT estop THEN
    state := 0;
    manA := FALSE;
    manB := FALSE;
    manC := FALSE;
    manD := FALSE;
    manMix := FALSE;
    valveARun := FALSE;
    valveBRun := FALSE;
    valveCRun := FALSE;
    valveDRun := FALSE;
    mixMotorRun := FALSE;


ELSIF NOT opeMode THEN

    IF prevOpeMode THEN
        state := 0;
        manA := FALSE;
        manB := FALSE;
        manC := FALSE;
        manD := FALSE;
        manMix := FALSE;
    END_IF
    IF valveAStart AND NOT prevValveAStart THEN
        manA := NOT manA;
    END_IF
    IF valveBStart AND NOT prevValveBStart THEN
        manB := NOT manB;
    END_IF
    IF valveCStart AND NOT prevValveCStart THEN
        manC := NOT manC;
    END_IF
    IF valveDStart AND NOT prevValveDStart THEN
        manD := NOT manD;
    END_IF
    IF mixMotorStart AND NOT prevMixMotorStart THEN
        manMix := NOT manMix;
    END_IF
    valveARun := manA;
    valveBRun := manB;
    valveCRun := manC;
    valveDRun := manD;
    mixMotorRun := manMix;


ELSE

    IF NOT prevOpeMode THEN
        state := 0;
        valveARun := FALSE;
        valveBRun := FALSE;
        valveCRun := FALSE;
        valveDRun := FALSE;
        mixMotorRun := FALSE;
    END_IF

    CASE state OF
        0:  
            valveARun := FALSE;
            valveBRun := FALSE;
            valveCRun := FALSE;
            valveDRun := FALSE;
            mixMotorRun := FALSE;

            IF autoStart AND NOT prevAutoStart THEN
                state := 10;
                valveARun := TRUE;
            END_IF

        10: 
            valveARun := TRUE;
            valveBRun := FALSE;
            valveCRun := FALSE;
            valveDRun := FALSE;
            mixMotorRun := FALSE;
            IF levelSensor >= 50 THEN
                valveARun := FALSE;
                valveBRun := TRUE;
                state := 20;
            END_IF

        20: 
            valveARun := FALSE;
            valveBRun := TRUE;
            valveCRun := FALSE;
            valveDRun := FALSE;
            mixMotorRun := FALSE;
            IF levelSensor >= 80 THEN
                valveBRun := FALSE;
                IF processMode THEN

                    valveCRun := TRUE;
                    state := 35;
                ELSE

                    mixMotorRun := TRUE;
                    state := 40;
                END_IF
            END_IF

        35: 
            valveARun := FALSE;
            valveBRun := FALSE;
            valveCRun := TRUE;
            valveDRun := FALSE;
            mixMotorRun := FALSE;
            IF levelSensor >= 100 THEN
                valveCRun := FALSE;
                mixMotorRun := TRUE;
                state := 40;
            END_IF

        40: 
            valveARun := FALSE;
            valveBRun := FALSE;
            valveCRun := FALSE;
            valveDRun := FALSE;
            mixMotorRun := TRUE;
            IF mixMotorComplete THEN
                mixMotorRun := FALSE;
                valveDRun := TRUE;
                state := 50;
            END_IF

        50: 
            valveARun := FALSE;
            valveBRun := FALSE;
            valveCRun := FALSE;
            valveDRun := TRUE;
            mixMotorRun := FALSE;
            IF autoStart AND NOT prevAutoStart THEN
                valveDRun := FALSE;
                valveARun := TRUE;
                state := 10;
            END_IF
    END_CASE
END_IF


prevAutoStart := autoStart;
prevValveAStart := valveAStart;
prevValveBStart := valveBStart;
prevValveCStart := valveCStart;
prevValveDStart := valveDStart;
prevMixMotorStart := mixMotorStart;
prevOpeMode := opeMode;
